{
  "src/vok/rules.ts": "import { WorldProtocol, Operation, EntityState } from '../types';

export const rules = {
  reset: (): EntityState => {
    return {
      tal: 'nim',
      fen: 'nim',
    };
  },

  applyOperation: (state: EntityState, op: Operation): EntityState => {
    if (op.type === 'moveTal') {
      return {
        ...state,
        tal: op.to,
      };
    }

    if (op.type === 'moveFen') {
      return {
        ...state,
        fen: op.to,
      };
    }

    if (op.type === 'boostTalFen') {
      return {
        tal: 'pex',
        fen: 'pex',
      };
    }

    return state;
  },

  isValidOperation: (state: EntityState, op: Operation): boolean => {
    if (op.type === 'moveTal') {
      return state.tal !== op.to;
    }

    if (op.type === 'moveFen') {
      return state.fen !== op.to;
    }

    if (op.type === 'boostTalFen') {
      return state.tal === 'nim' && state.fen === 'nim';
    }

    return false;
  },
};
",
  "src/protocol_adapter.ts": "import { WorldProtocol, EntityState, Operation, AbstractSnapshot } from './types';
import { rules } from './vok/rules';

let currentState: EntityState = rules.reset();

export const protocol: WorldProtocol = {
  reset: () => {
    currentState = rules.reset();
  },

  applyOperation: (op: Operation) => {
    if (rules.isValidOperation(currentState, op)) {
      currentState = rules.applyOperation(currentState, op);
      return true;
    }
    return false;
  },

  getEntityState: () => {
    return { ...currentState };
  },

  toAbstractSnapshot: (): AbstractSnapshot => {
    return {
      tal: currentState.tal,
      fen: currentState.fen,
    };
  },
};
"
